import {confirmModal} from './modal-manager.js';
import {node,section,action,modal,renderForm,renderTable} from './proto-ui.js';
/** Generic JSON-backed CRUD view; consuming apps provide only fields and endpoint. */
export function createGeneratedCrudView(config){
 const fields=config.fields||[],columns=fields.filter(f=>f.showInTable!==false).slice(0,8).map(f=>({key:f.key,label:f.label||f.key}));
 return {title:config.title||'Records',type:'crud',components:[],async onMount({host,api}){
  const panel=section(host,config.title,'Generated by REBEL View Designer · Persistent REST CRUD');const results=node('div');panel.append(results);let table;
  const url=config.endpoint;
  async function load(){const result=await api.request(url);const rows=result.items||[];if(table)table.refresh(rows);else table=renderTable(results,{columns,items:rows,actions:rowActions,pageSize:5,caption:config.title,onNew:()=>edit(null),newLabel:'New Record'});}
  function edit(record){const {dialog,form}=modal(record?'Edit Record':'New Record'),extract=renderForm(form,fields,record||{});const bar=node('div',null,'toolbar');bar.append(action('Cancel',()=>dialog.close()),action(record?'Save Changes':'Create Record',async()=>{if(!form.reportValidity())return;try{await api.request(url+(record?'/'+record.id:''),{method:record?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(extract())});dialog.close();await load();window.rebelDemo?.notify('Record saved successfully')}catch(e){window.rebelDemo?.notify(e.message,true)}},'btn btn--primary'));form.append(bar)}
  function rowActions(row,cell,rowNumber){cell.append(action('Edit',()=>edit(row)),action('Delete',async()=>{if(!await confirmModal(`Are you sure you want to delete record #${rowNumber}? This action cannot be undone.`))return;try{await api.request(url+'/'+row.id,{method:'DELETE'});await load();window.rebelDemo?.notify('Record deleted')}catch(e){window.rebelDemo?.notify(e.message,true)}}))}
  await load();
 }};
}
export function createGeneratedTableView(config){return {title:config.title,type:'table',components:[],async onMount({host,api}){const panel=section(host,config.title,'Read-only API table');const rows=await api.request(config.endpoint);renderTable(panel,{columns:(config.fields||[]).map(f=>({key:f.key,label:f.label||f.key})),items:rows.items||[],pageSize:5})}}}
export function createGeneratedBlankView(config){return {title:config.title,type:'custom',components:[],async onMount({host}){const panel=section(host,config.title);panel.append(node('p','This custom view is ready for components.','muted'))}}}
/** Standalone create-only form generated from the same reusable field schema. */
export function createGeneratedFormView(config){return {title:config.title||'New Record',type:'new',components:[],async onMount({host,api}){const panel=section(host,config.title||'New Record','Standalone form · all controls rendered by REBEL');const form=node('form',null,'cv-form-grid');panel.append(form);const collect=renderForm(form,config.fields||[]);const submit=action('Create Record',async()=>{if(!form.reportValidity())return;try{await api.request(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(collect())});window.rebelDemo?.notify('Record created');form.reset()}catch(e){window.rebelDemo?.notify(e.message,true)}},'btn btn--primary');form.append(submit)}}}
